#!/usr/bin/env bash
# Batsy one-file installer for Fedora:  bash batsy-install.sh
set -euo pipefail
DEST="$HOME/batsy"
echo "Unpacking Batsy into $DEST ..."
mkdir -p "$DEST"
sed -n '/^__BATSY_ARCHIVE__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$DEST"
chmod +x "$DEST/install.sh"
exec bash "$DEST/install.sh"
__BATSY_ARCHIVE__

